action.command:
cat /workdir/solution.csv | head -5 && echo '---' && python3 -c "
import csv
gt={r['PassengerId']:r['label'] for r in csv.DictReader(open('/workdir/data/ground_truth_female.csv'))}
pred={r['PassengerId']:r['prediction'] for r in csv.DictReader(open('/workdir/solution.csv'))}
tp=sum(1 for k in gt if pred.get(k)==gt[k] and gt[k]=='1')
fp=sum(1 for k in gt if pred.get(k)=='1' and gt[k]=='0')
fn=sum(1 for k in gt if pred.get(k)=='0' and gt[k]=='1')
f1=2*tp/(2*tp+fp+fn) if (2*tp+fp+fn) else 0
print('F1 =', f1, 'n=', len(gt), 'matched_ids=', set(gt)==set(pred))
"

